import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Bernini: Latent Semantic Planning for Video Diffusion","description":"","frontmatter":{"title":"Bernini: Latent Semantic Planning for Video Diffusion","arxiv":"2605.22344","date":"2026-05-21","authors":"Bernini Team (ByteDance): Chenchen Liu, Junyi Chen, Lei Li, Lu Chi, Mingzhen Sun, Zhuoying Li, Yi Fu, Ruoyu Guo, Yiheng Wu, Ge Bai, Zehuan Yuan","categories":"cs.CV, cs.AI, cs.MM","topics":"统一生成与编辑, 语义规划接口, 视频扩散","outline":[2,2]},"headers":[],"relativePath":"papers/2605.22344.md","filePath":"papers/2605.22344.md","lastUpdated":null}'),e={name:"papers/2605.22344.md"};function l(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="bernini-latent-semantic-planning-for-video-diffusion" tabindex="-1">Bernini: Latent Semantic Planning for Video Diffusion <a class="header-anchor" href="#bernini-latent-semantic-planning-for-video-diffusion" aria-label="Permalink to &quot;Bernini: Latent Semantic Planning for Video Diffusion&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2605.22344" target="_blank" rel="noreferrer">2605.22344</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-05-21</td></tr><tr><td><strong>作者</strong></td><td>Bernini Team (ByteDance): Chenchen Liu, Junyi Chen, Lei Li, Lu Chi, Mingzhen Sun, Zhuoying Li, Yi Fu, Ruoyu Guo, Yiheng Wu, Ge Bai, Zehuan Yuan</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI, cs.MM</td></tr><tr><td><strong>一句话</strong></td><td>让 MLLM 用 masked generative 的方式在自己原生的 ViT embedding 空间里&quot;画&quot;出目标语义，再把这份语义计划交给 DiT 渲染像素，两端因此几乎可以各自独立训练。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>MLLM 会读长指令、能对多张参考图做 grounding、能把答案锚在复杂多模态上下文里；diffusion 会把像素画得逼真。把两者合成一个既懂意图又能生成的系统是明摆着的下一步，难点全在<strong>接口</strong>：这两个模型之间应该传什么。</p><p>传得太窄（几个 learnable query token、或者干脆传重写后的文本）会丢掉视觉细节和空间布局；传得太宽（把 MLLM 隐状态整体塞进去）则要求两端联合训练，代价是两边的预训练能力互相干扰。Bernini 给出的答案是：传 MLLM <strong>自己的 ViT embedding</strong>。这个选择的直接后果是 planner 和 renderer 可以各自独立训练、只做轻量 co-train，所以 MLLM 的理解能力不被稀释，而 diffusion 的生成保真度也不被破坏。论文用 VBench 给出的证据是，扩展成统一框架后 T2V 总分 84.64，和底座 Wan2.2-A14B 的 84.79 基本持平 —— 加了编辑和参考生成能力，没有付出生成质量的代价。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文把相关工作分成两条线，划得很清楚。</p><p><strong>统一多模态骨干</strong>：Emu3 把文本/图像/视频都离散化进共享词表，从头训一个 transformer 做纯 next-token prediction；Janus 保留统一自回归骨干但把理解和生成的视觉编码器拆成两路；Show-o 在单个 transformer 里把文本自回归和图像离散 diffusion 耦合；BAGEL 用 Mixture-of-Transformer-Experts 让理解专家和生成专家通过共享 self-attention 交互。这条线的共同代价是从头训或大改骨干，预训练能力难以完整保留。</p><p><strong>MLLM 作为条件器</strong>：MetaQuery 和 Bifrost-1 通过 cross-attention 传输出 token 或少量 query token（Bifrost-1 用 patch-level CLIP latent）；SEED-X、DreamLLM、Emu 直接用隐状态驱动外部图像解码器；到视频这一侧，UniVideo 和 VInO 把 MLLM 隐状态（可选配 query token 或交织多模态上下文，外加参考的 VAE latent）喂给视频 diffusion 骨干。Bernini 属于同一范式，但把接口<strong>锚定在 MLLM 原生的 ViT embedding 空间而非输出隐状态</strong>。作者的理由是：MLLM 本来就在这个空间里表示和推理视觉内容，训它在这个空间里规划目标，与其预训练表示天然对齐，需要的适配最少。</p><p>数据侧的不足也被点名：现有视频编辑数据集规模小、噪声大、构造流水线不成熟，这直接限制了通用视频编辑模型的训练。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从两个观察出发，两个都不依赖本文的贡献。</p><p>第一，diffusion 的条件可以干净地分解成<strong>语义引导</strong>和<strong>细节保持</strong>两部分：高层内容由一个紧凑信号决定，而精细保真（编辑时还包括与源视频的一致性）需要稠密的像素级 latent（VAE 特征）。关键在于语义信号<strong>不需要高分辨率也能起效</strong> —— 几十个语义 token 就足以指定一整个场景。</p><p>第二，MLLM 天然适合语义推理：解析长指令、在多个参考上 grounding、形成&quot;输出应该是什么样&quot;的内部表示。</p><p>把两条拼起来，分工就出来了：MLLM 做语义规划，diffusion 专心合成，只在需要保细节的地方才用像素级特征。接下来的问题是拿什么表示承载语义信号。这里有一个不太显然但很关键的判断：<strong>不要发明新的接口空间</strong>。MLLM 内部已经有一个成熟的视觉表示空间了，就是它的 ViT embedding 空间。训 MLLM 在这个空间里预测目标，等于让它做一件与预训练最接近的事。</p><p>再往下，如何&quot;预测&quot;一段还不存在的视觉内容？自回归逐 token 生成对视觉语义并不合适 —— 视觉 latent 本质上是双向的。masked generative modeling（MaskGIT / MAR 那一支）正好对上：训练时随机 mask 一部分目标 token 让模型从可见部分和多模态上下文推断，推理时从全 mask 开始迭代填充。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>不要在 MLLM 和 diffusion 之间新造一个接口，直接用 MLLM 已有的 ViT embedding 空间当桥。让 MLLM 以 masked generative 的方式在这个空间里把目标&quot;想&quot;出来，diffusion 只负责把这份语义计划渲染成像素、并用源 VAE 特征补细节。因为接口是语义而非隐状态，两端可以各练各的、最后轻量对齐，谁的预训练能力都不被牺牲。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以一个真实的编辑任务为例：给定一段小狗的视频和指令&quot;改变小狗的动作&quot;。</p><p><strong>统一输入序列化</strong>。T2V、T2I、S2V、图像/视频编辑全部序列化成同一套 token 序列，MLLM 编码整段序列得到上下文化隐状态：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord mathbf">z</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0936em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">MLLM</span></span><span class="mopen">(</span><span class="mord mathbf">t</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf" style="margin-right:0.016em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7144em;"><span style="top:-2.453em;margin-left:-0.016em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">src</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf" style="margin-right:0.016em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7144em;"><span style="top:-2.453em;margin-left:-0.016em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">src</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf" style="margin-right:0.016em;">v</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8436em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">tgt</span></span></span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span></span></p><p>训练时 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7936em;"></span><span class="mord"><span class="mord mathbf" style="margin-right:0.016em;">v</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7936em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">tgt</span></span></span></span></span></span></span></span></span></span></span></span></span> 被随机部分 mask，推理时初始化为全 mask。</p><p><strong>Planner（Qwen2.5-VL-7B）</strong>。mask 比例从任务相关的 Beta 分布采样。masked 位置的隐状态送进一个 ViT embedding decoder（MLP + ResNet 预测头），用 flow-matching 目标在 ViT embedding 空间里预测 ground-truth ViT embedding。推理时做 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 步迭代细化，第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 步的 mask 比例按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.095em;vertical-align:-0.345em;"></span><span class="mop">cos</span><span class="mopen">(</span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6954em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">2</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">π</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2251em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8801em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose">)</span></span></span></span> 调度，默认 25 步规划、每步 decoder 内做 5 步 flow-matching 去噪。作者实测这部分开销相对 DiT 渲染近乎可忽略。</p><p><strong>Renderer（Wan2.2-A14B）</strong>。取 MLLM 倒数第二层隐状态，过一个零初始化的单层 MLP，与原有 T5 特征拼接后作为条件 —— 这样既保住 Wan2.2 的文本条件先验，又注入了高层语义。编辑任务额外注入源视频/源图的 VAE 特征保细节。T2V 用 60 步去噪，其余任务 40 步。</p><p><strong>SA-3D RoPE</strong>。统一序列里目标 token、源视频 token、参考图 token 可能落在相同的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">h</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mclose">)</span></span></span></span> 坐标上，attention 分不清它们的身份。做法是给每个 segment 一个索引 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span>（目标为 0，输入为 1,2,…），构造全维旋转频率向量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0592em;vertical-align:-0.2769em;"></span><span class="mord"><span class="mord mathbf">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7823em;"><span style="top:-2.4231em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">seg</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2769em;"><span></span></span></span></span></span></span></span></span></span>，与原三维旋转位置逐元素复数相乘：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9674em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6813em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf">r</span></span><span style="top:-3.3634em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">h</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathbf">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">h</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⊙</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0592em;vertical-align:-0.2769em;"></span><span class="mord"><span class="mord mathbf">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7823em;"><span style="top:-2.4231em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">seg</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2769em;"><span></span></span></span></span></span></span></span></span></span>。</p><p><strong>三阶段训练</strong>。Stage I 只训 planner + ViT decoder（256P，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">text</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.2</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">visual</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>）；Stage II 只训 DiT（480P/16fps，pair 数据用线性衰减采样，前期高比例后期归零）；Stage III 轻量联合训练（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9805em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">n</span><span class="mord mathnormal mtight">tp</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.2</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight">u</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>），后期再引入 CoT 数据。</p><p><strong>数据</strong>。2000 万视频对（X-CLIP 相似度筛在 0.65–0.95，时长 2–10 秒，人物/非人物 1:1，每原视频最多 100 对）、近 3000 万图像对（来自教程视频，CLIP 相似度 0.75–0.95）、约 1000 万交织图文；视频编辑数据用&quot;先训传播模型 + 强图像编辑器编首帧&quot;的方式提质，再用 I2V/V2V 双分支加权融合造出动作自适应的编辑数据；约 100 万条 self-text CoT 数据。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p><strong>总目标函数</strong>是三项加权：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9805em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">text</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ntp</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">visual</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">visual</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">dit</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">dit</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ntp</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 是标准 next-token prediction，作用是防止 MLLM 在被改造成 planner 的过程中丢掉语言能力。后两项都是 flow-matching，形式相同，只是目标表示和速度场不同 —— 一个在连续 ViT embedding 空间，一个在 VAE latent 空间。flow-matching 的 intuition：不去建模逐步加噪的马尔可夫链，而是直接回归从噪声到数据的直线路径上的速度场，训练更稳、采样步数可压得更低。</p><p><strong>mask 比例的设计</strong>值得单独说。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">Beta</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mclose">)</span></span></span></span>，各任务的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mclose">)</span></span></span></span> 不同：T2I 是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">5.0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1.1</span><span class="mclose">)</span></span></span></span>，一路到 V2V/IV2V 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">12.0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.9</span><span class="mclose">)</span></span></span></span>。Beta 分布在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 增大、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span> 减小时概率质量向 1 集中，也就是<strong>输入越信息丰富，目标被 mask 得越狠</strong>。原因很直接：编辑任务里源视频和目标高度相关，如果留太多可见的目标 token，模型只要复制就行，语义预测任务会退化得毫无难度。加大 mask 比例是在堵这条捷径，逼 planner 从高层多模态上下文而非泄漏的目标信息里推断语义。</p><p><strong>推理时的多条件引导</strong>被分解成一个无条件基项加四个增量项。设 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">ϵ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2572em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord amsrm mtight">∅</span><span class="mpunct mtight">,</span><span class="mord amsrm mtight">∅</span><span class="mpunct mtight">,</span><span class="mord amsrm mtight">∅</span><span class="mpunct mtight">,</span><span class="mord amsrm mtight">∅</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 为完全无条件预测，逐步加入源视频 VAE、源图 VAE、文本、目标语义 embedding，各自的增量为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord">Δ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">vid</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord">Δ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">img</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord">Δ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">txt</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord">Δ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">tgt</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，最终预测为</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">ϵ</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">ϵ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2572em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord amsrm mtight">∅</span><span class="mpunct mtight">,</span><span class="mord amsrm mtight">∅</span><span class="mpunct mtight">,</span><span class="mord amsrm mtight">∅</span><span class="mpunct mtight">,</span><span class="mord amsrm mtight">∅</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">vid</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord">Δ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">vid</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">img</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord">Δ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">img</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">txt</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord">Δ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">txt</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">tgt</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord">Δ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">tgt</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span></span></p><p>这是 classifier-free guidance 的多条件推广。写成嵌套增量而非独立差分，好处是每个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span></span></span></span> 度量的是&quot;在已有条件基础上再加一个条件带来的变化&quot;，避免了条件之间重复计数。各任务的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span></span></span></span> 单独调（例如 V2V 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">tgt</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 只有 0.5，而 S2V 和 RV2V 是 1.5），可以推断这反映了编辑任务更依赖源特征、参考生成更依赖语义计划的直觉。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>统一化会不会牺牲基础生成能力？</strong> 在 VBench 上比自己的底座。答案是几乎不会：Bernini 总分 84.64 对 Wan2.2-A14B 的 84.79。</p><p><strong>编辑上表现如何？</strong> 作者自建 Bernini-Bench（300 个 case、22 类编辑、含动作编辑/位置编辑/因果推理编辑/焦点变化这些别的 benchmark 不覆盖的类型），同时用 MLLM 打分和人工 side-by-side。Bernini-V2V 上整体分 3.49，高于 Wan2.7 的 3.30 和 Kling O3 的 3.05；分维度看，instruction following 和生成质量与 Wan2.7 相当，<strong>video consistency 明显更强</strong>（3.51 vs 3.11）。人工 SBS 复现了同一结论：全面胜过 Kling O3，与 Wan2.7 打平，一致性维度优势显著。公开基准上，OpenVE 整体 4.04 大幅超过次优的 VINO 3.18；EditVerse 编辑质量 8.02 创新高；FiVE 的 VQA 类指标 78.16 领先。</p><p><strong>subject-to-video 上呢？</strong> OpenS2V-Eval 总分 62.94，超过 Kling O3（59.19）和 RefAlign-14B（60.42）。最扎眼的是 FaceSim 78.20，比次优的 Kling O3（57.20）高出 20 分以上。不过要注意，同表里 Bernini 的 Aesthetic（44.14）和 Motion Smoothness（93.66）并不领先 —— 优势高度集中在身份一致性上。</p><p><strong>SA-3D RoPE 真的必要吗？</strong> 对照标准 3D RoPE 和&quot;3D RoPE + 可学习 segment embedding&quot;。结论是加性 segment embedding 虽然改善了参考一致性，但两个基线都仍有明显的 reference leakage：参考图的外观细节泄漏到目标的非目标区域（背景、鸭头）。只有把 segment 索引做成相位调制、与时空位置解耦，attention 才能可靠区分 segment 角色。这个消融是定性的（图示），没有给定量数字。</p><p><strong>CoT 有多少贡献？</strong> baseline 3.12；用 Qwen2.5-VL-7B（planner 的初始化模型）当 prompt enhancer 只到 3.20，而模型自己的 self-text reasoning 到 3.33 —— 作者据此论证 planner 已经长出了超过其初始化模型的文本推理能力。换成 GPT-5.4 做 prompt enhancer 到 3.49，再叠加 self-vision-text reasoning 到 3.52。</p><p>论文在结论里承认得很直接：复杂编辑仍<strong>依赖强 LLM 重写器</strong>提供足够结构化的指令，说明其原生推理能力还不够；且 subject-to-video 的视觉质量仍不及 Wan2.7 这类更强的系统。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：把 MLLM 和 diffusion 缝在一起的关键是选对接口，Bernini 选的是 MLLM 自己的 ViT embedding 空间。planner 用 masked generative 方式在这个空间里迭代填出目标语义，renderer 拿它当条件在 VAE latent 空间做 flow matching，编辑时再补源 VAE 特征保细节。因为接口是语义，两端可以分开预训练、只做轻量联合对齐，VBench 上 84.64 对底座 84.79 证明基础能力没被牺牲。任务相关的 Beta mask 比例是让编辑任务不退化成复制的关键设计，SA-3D RoPE 则用相位调制解决了多 segment 共坐标导致的参考泄漏。实测优势集中在一致性维度：编辑的 video consistency 和 S2V 的 FaceSim（78.20 vs 次优 57.20）。</p><p><strong>3 句话版</strong>：用 MLLM 原生的 ViT embedding 当语义接口，planner 与 renderer 得以各自保留预训练能力。任务相关的 mask 调度堵住了编辑任务里的复制捷径。收益集中在一致性，而非画面质量。</p><p><strong>1 句话版</strong>：接口选在模型已有的表示空间里，比新造一个接口更省，也更保命。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的一条是：<strong>ViT embedding 空间足以承载完整的目标语义计划</strong>。整个架构的经济性都建立在&quot;语义信号不必高分辨率&quot;这个断言上 —— 少量语义 token 就能指定整个场景。如果这个空间在某些属性上存在<strong>系统性盲区</strong>，那么 planner 无论迭代多少步都规划不出来，而 renderer 只能靠 T5 文本特征和源 VAE 特征去兜底。</p><p>ViT/CLIP 类表示的已知弱点正好落在这些地方：精确计数、细粒度空间关系、文字渲染、属性绑定。论文的实验分布与这个担忧是一致的 —— 优势集中在身份一致性（ViT 表示最擅长的语义类别），而 OpenVE 的 subtitle edit 一项 Bernini 只有 3.57，是它八个子项里相对靠后的成绩之一。作者自己也承认复杂编辑仍需外部 LLM 重写器，可以推断这正是在用语言侧的结构化补偿语义空间承载力的不足。</p><p>论文没有做的关键实验：改变 planner 输出的语义 token 数量，看质量如何随之变化。缺了这条曲线，&quot;少量语义 token 足够&quot;就仍然是一个假设而不是被验证的结论。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不训练完整系统，一周内可做：</p><ul><li>数据：取 100 组&quot;源图 + 编辑指令 + 目标图&quot;三元组，指令刻意分成两类 —— 语义类（换物体、换风格、换身份）和结构类（数量变化、精确空间关系、文字内容修改）。</li><li>实现：不做生成。用任意开源 MLLM 的 ViT encoder 分别编码源图和目标图，训一个小的 MLP+ResNet 头，从&quot;源图 ViT embedding + 指令文本 embedding&quot;回归目标图的 ViT embedding，即 Bernini 的 planner 那一步的极简版。</li><li>测量：预测 embedding 与真值 embedding 的余弦相似度，按两类指令分组统计；再用一个现成的 ViT-embedding-to-image 检索器，看 top-1 检索回的图像是否符合指令。</li><li>判据：若结构类指令的相似度和检索准确率显著低于语义类，则支持&quot;ViT 空间存在系统性盲区&quot;的判断，Bernini 的适用范围需要限定；若两类接近，则反驳该担忧，说明瓶颈在别处（例如 renderer 的条件注入方式）。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是给 §7 的编辑结果找<strong>替代解释</strong>：Bernini 在 video consistency 上的优势，可能根本不来自&quot;语义规划&quot;，而来自它在编辑时额外注入了<strong>源视频的 VAE 特征</strong>。VAE latent 保留稠密像素信息，把它作为条件本身就会强烈约束非编辑区域不变。如果是这样，那么 ViT 语义接口的贡献被高估了，而消融图（Fig. 16）只做了定性展示，没有把&quot;去掉 ViT 接口&quot;与&quot;去掉源 VAE 特征&quot;分开定量对比。</p><p>具体实验：在 Bernini-V2V 上跑三个变体 —— 完整模型、去 ViT 语义接口但保留源 VAE、保留 ViT 但去源 VAE，分别报 IF/VC/GQ 三个维度的定量分数。如果&quot;去 ViT 保 VAE&quot;在 VC 上几乎不掉，那么一致性优势的归因就要改写；如果它在 IF 上大掉而 VC 保持，则说明两条通路分工明确，恰好印证论文的分解假说。</p><p>另一类可预测的失败：论文的 T2V 分数与底座持平被当作&quot;没有付出代价&quot;的证据，但持平也意味着<strong>语义规划对纯文生视频没有带来任何增益</strong>。在 T2V 场景里没有源视觉输入，planner 只能从文本推出 ViT embedding，此时它相比 T5 文本特征多提供了什么？VBench 84.64 vs 84.79 这个略低的数字，可以被解读为语义规划在这一任务上是纯开销。论文没有针对 T2V 单独做&quot;有无 planner&quot;的消融，因此该解读只是推测。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：planner 的 25 步迭代对所有任务一视同仁，且规划完就结束，renderer 渲染出来的结果<strong>从不反馈给 planner</strong>。这意味着当渲染结果偏离计划时（比如参考泄漏、指令未执行），系统没有任何察觉机制，只能靠外部 LLM 重写指令来&quot;预防&quot;。作者承认对强重写器的依赖，正是这个开环结构的症状。</p><p><strong>新 framing</strong>：把 planner–renderer 从<strong>开环的一次性规划</strong>改造成<strong>闭环的语义一致性校验</strong>。核心动作是把 planner 反过来用一次：渲染出的视频重新过 ViT encoder，得到实际达成的语义 embedding，与规划的 embedding 做比对；差异不再只是一个标量误差，而是一个<strong>定位到具体 token 的语义偏差图</strong>，可以直接指出&quot;哪个区域没按计划渲染&quot;。这不是加个 refinement 模块，而是把语义空间从&quot;传递介质&quot;升格为&quot;可测量的验收标准&quot;，目标函数从生成质量变成计划-执行的对齐度。</p><p><strong>可借鉴的相邻工具</strong>：控制论里的 model-predictive control 提供了在执行中反复重规划的框架；自动微分式的 test-time optimization（如 diffusion 的 guidance 反传）提供了把语义偏差转成 latent 修正量的现成手段；两者都不需要重新训练。</p><p><strong>第一个实验</strong>：在 Bernini-Bench 那 22 类里挑出模型失败率最高的几类（论文定性提到的参考泄漏场景是好的起点），对每个失败样本计算&quot;规划语义 vs 实际渲染语义&quot;的 token 级余弦距离，检验这个距离能否在<strong>不看真值</strong>的前提下预测人工标注的失败位置。若相关性显著，就说明语义偏差是可自动检测的，闭环重渲染有了触发信号；若相关性很弱，则说明 ViT embedding 对渲染缺陷不敏感，闭环应当建在别的表示上，这本身也是关于接口选择的重要负面结论。</p>',64)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
